}

.island-chip__title {
  flex: 1 1 auto;
  text-align: left;
}

.island-chip__project {
  flex: 0 1 auto;
  color: var(--fg-2);
}

.island-chip__count,
.island-chip__separator {
  flex: 0 0 auto;
  color: var(--fg-2);
}

.island-scrim {
  position: fixed;
  inset: 0;
  z-index: 120;
